SELECT status, CASE WHEN shipping_fee >= 35 THEN 'high' WHEN shipping_fee >= 9 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, ROUND((100 * SUM(CASE WHEN channel = 'web' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_web, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values, ROUND((100 * SUM(CASE WHEN channel = 'store' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_store FROM orders WHERE channel IN ('store', 'mobile') GROUP BY status, shipping_fee_bucket
